((root)=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const families=new Set(['inherit','sans','serif']);
 function color(value){if(value===undefined||value===null||value==='')return '';const v=String(value).trim();if(/^#[a-f0-9]{6}$/i.test(v))return v.toLowerCase();if(/^#[a-f0-9]{3}$/i.test(v))return '#'+[...v.slice(1)].map(x=>x+x).join('').toLowerCase();const m=v.match(/^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$/i);if(m&&m.slice(1).every(x=>Number(x)<=255))return '#'+m.slice(1).map(x=>Number(x).toString(16).padStart(2,'0')).join('');throw Error('HEX(#RRGGBB) 또는 RGB(0–255)를 입력해주세요.');}
 function merge(runs){const result=[];for(const r of runs){if(!r.text)continue;const font=families.has(r.font)?r.font:'inherit',tone=color(r.color),run={text:r.text,font,...(tone?{color:tone}:{})};if(result.at(-1)?.font===font&&(result.at(-1)?.color||'')===tone)result.at(-1).text+=r.text;else result.push(run);}return result;}
 function validate(runs,plain,limit=2048){if(runs===undefined||runs===null)return [];if(!Array.isArray(runs)||runs.length>limit)throw Error('글자 서식은 최대 '+limit+'개입니다.');let result=runs.map(r=>{if(!r||typeof r.text!=='string'||!families.has(r.font||'inherit'))throw Error('글자 서식을 확인해주세요.');const tone=color(r.color);return {text:r.text,font:r.font||'inherit',...(tone?{color:tone}:{})};});const joined=result.map(r=>r.text).join('');if(joined.trim()!==String(plain).trim())throw Error('본문과 글자 서식이 일치하지 않습니다.');let start=joined.length-joined.trimStart().length,end=joined.trimEnd().length,offset=0;result=result.map(r=>{const left=Math.max(0,start-offset),right=Math.min(r.text.length,end-offset);offset+=r.text.length;return {...r,text:r.text.slice(left,Math.max(left,right))};});return merge(result);}
 function patch(runs,start,end,change){const total=runs.map(r=>r.text).join('').length;if(!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>total||end<=start)throw Error('글자를 먼저 선택해주세요.');let offset=0,result=[];for(const r of runs){const from=Math.max(0,start-offset),to=Math.min(r.text.length,end-offset);if(to>from){if(from)result.push({...r,text:r.text.slice(0,from)});result.push({...r,...change,text:r.text.slice(from,to)});if(to<r.text.length)result.push({...r,text:r.text.slice(to)});}else result.push({...r});offset+=r.text.length;}return merge(result);}
 function mark(runs,start,end,font){if(!families.has(font))throw Error('글꼴을 선택해주세요.');return patch(runs,start,end,{font,...(font==='inherit'?{color:undefined}:{})});}
 function markColor(runs,start,end,value){return patch(runs,start,end,{color:color(value)||undefined});}
 function markup(runs,plain){if(!Array.isArray(runs)||runs.map(r=>r.text).join('')!==plain)return esc(plain);return runs.map(r=>{const tone=color(r.color),font=families.has(r.font)?r.font:'inherit';return tone||font!=='inherit'?'<span data-font="'+font+'"'+(font!=='inherit'?' class="cms-inline-'+font+'"':'')+(tone?' data-color="'+tone+'"':'')+'>'+esc(r.text)+'</span>':esc(r.text);}).join('');}
 function read(node){const result=[];const push=(text,font,tone)=>{if(text)result.push({text,font,...(tone?{color:tone}:{})});};function walk(el,font='inherit',tone=''){if(el.nodeType===3){push(el.nodeValue,font,tone);return;}if(el.nodeType!==1&&el.nodeType!==11)return;const own=el.getAttribute?.('data-font'),ownColor=el.getAttribute?.('data-color');if(families.has(own))font=own;if(ownColor)tone=color(ownColor);if(el.nodeName==='BR'){push('\n',font,tone);return;}if(['DIV','P'].includes(el.nodeName)&&result.length&&!result.at(-1).text.endsWith('\n'))push('\n',font,tone);for(const child of el.childNodes)walk(child,font,tone);}for(const child of node.childNodes)walk(child);return {runs:merge(result),text:result.map(r=>r.text).join('')};}
 function offset(el,node,pos){const r=document.createRange();r.selectNodeContents(el);r.setEnd(node,pos);return read(r.cloneContents()).text.length;}
 function select(el,start,end){const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node,total=0,first=null,last=null;while(node=walker.nextNode()){const length=node.nodeValue.length;if(!first&&start<=total+length)first=[node,Math.max(0,start-total)];if(end<=total+length){last=[node,Math.max(0,end-total)];break;}total+=length;}if(!first||!last)return;const r=document.createRange();r.setStart(...first);r.setEnd(...last);const selection=getSelection();selection.removeAllRanges();selection.addRange(r);}
 root.NEMO_RICH={merge,validate,mark,markColor,color,markup,read,offset,select};if(typeof module!=='undefined')module.exports=root.NEMO_RICH;
})(typeof window==='undefined'?globalThis:window);
